def candidates(template,S):
 out=[]
 for nm,U in transforms(template):
  for sr,sc in S:
   for ur,uc in U:
    dr,dc=sr-ur,sc-uc
    if all((r-dr,c-dc) in U for r,c in S):
     out.append((nm,dr,dc,U))
 # unique
 uniq=[]
 for x in out:
  if not any((x[0],x[1],x[2])==(y[0],y[1],y[2]) for y in uniq): uniq.append(x)
 return uniq
def analyze(template,S,actual):
 rc=np.mean([r for r,c in S]),np.mean([c for r,c in S])
 cand=candidates(template,S)
 rows=[]
 for nm,r,c,U in cand:
  coords={(r+rr,c+cc) for rr,cc in U}
  cen=(np.mean([x for x,y in coords]),np.mean([y for x,y in coords]))
  dist=np.linalg.norm(np.array(rc)-np.array(cen))
  rows.append((dist,nm,(r,c), (r,c)==actual))
 return sorted(rows)
